INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Денежно-кредитное регулирование и Банк России','Группа депутатов предлагает оценивать результативность Банка России по максимизации чистой прибыли. Какое положение закона корректирует критерий?','["Получение прибыли является единственной целью Банка России","Прибыль обязательна в размере не менее доходов федерального бюджета","Получение прибыли не является целью деятельности Банка России","Прибыль может устанавливаться целью исключительно решением губернатора"]'::jsonb,2,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_37570/0e58cddf536be1047c28b188ee5e495817a6ab71/','Основание — статья 3 указанного НПА; правильный порядок решения: Получение прибыли не является целью деятельности Банка России.',true),
('Денежно-кредитное регулирование и Банк России','В стратегии Центрального банка исключили развитие финансового рынка из перечня целей. Какова оценка?','["Развитие финансового рынка относится исключительно к задачам коммерческих банков","Развитие финансового рынка прямо закреплено среди целей Банка России","Финансовый рынок не упоминается в целях Банка России","Цель развития рынка допускается лишь при повышении ключевой ставки"]'::jsonb,1,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_37570/0e58cddf536be1047c28b188ee5e495817a6ab71/','Основание — статья 3 указанного НПА; правильный порядок решения: Развитие финансового рынка прямо закреплено среди целей Банка России.',true),
('Денежно-кредитное регулирование и Банк России','Предложен план Банка России, сосредоточенный на росте прибыли, но игнорирующий надёжность национальной платёжной системы. Какая цель упущена?','["Обеспечение стабильности и развитие национальной платёжной системы","Единоличное утверждение федерального бюджета","Назначение руководителей всех муниципальных банков","Передача денежной эмиссии региональным казначействам"]'::jsonb,0,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_37570/0e58cddf536be1047c28b188ee5e495817a6ab71/','Основание — статья 3 указанного НПА; правильный порядок решения: Обеспечение стабильности и развитие национальной платёжной системы.',true),
('Денежно-кредитное регулирование и Банк России','Министерство требует самостоятельно утверждать процентные ставки по операциям Банка России как свою внутреннюю функцию. Как распределены полномочия?','["Любые ставки по операциям ЦБ устанавливает финансовый орган субъекта","Ставки устанавливаются исключительно региональными парламентами","Ставки ЦБ определяют частные кредитные организации совместным соглашением","Установление инструментов денежно-кредитной политики относится к Банку России"]'::jsonb,3,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_37570/4f84b42935e2a5743f1b5e1591668be0c41b762d/','Основание — статья 4 указанного НПА; правильный порядок решения: Установление инструментов денежно-кредитной политики относится к Банку России.',true),
('Денежно-кредитное регулирование и Банк России','Правительство предлагает передать организацию наличного денежного обращения независимому региональному банку. Кто имеет установленную функцию?','["Каждый субъект вправе выпускать наличные деньги при положительном бюджете","Функцию осуществляет исключительно муниципальное казначейство","Банк России монопольно осуществляет эмиссию наличных и организует их обращение","Наличные деньги выпускаются по распоряжению каждой кредитной организации"]'::jsonb,2,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_37570/4f84b42935e2a5743f1b5e1591668be0c41b762d/','Основание — статья 4 указанного НПА; правильный порядок решения: Банк России монопольно осуществляет эмиссию наличных и организует их обращение.',true),
('Денежно-кредитное регулирование и Банк России','Один из крупных банков испытывает нехватку ликвидности; кто выполняет функцию кредитора последней инстанции в рамках закона?','["Региональная счётная палата","Банк России","Любое федеральное министерство","Муниципальная избирательная комиссия"]'::jsonb,1,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_37570/4f84b42935e2a5743f1b5e1591668be0c41b762d/','Основание — статья 4 указанного НПА; правильный порядок решения: Банк России.',true),
('Денежно-кредитное регулирование и Банк России','Финансовая организация утверждает, что банковский надзор полностью передан Правительству РФ. Какое полномочие установлено законом?','["Банк России осуществляет банковский надзор за кредитными организациями и банковскими группами","За кредитными организациями наблюдают исключительно муниципальные парламенты","Банковский надзор осуществляет только Федеральное Собрание","Банковский надзор отменён законом при действии цифрового рубля"]'::jsonb,0,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_37570/4f84b42935e2a5743f1b5e1591668be0c41b762d/','Основание — статья 4 указанного НПА; правильный порядок решения: Банк России осуществляет банковский надзор за кредитными организациями и банковскими группами.',true),
('Денежно-кредитное регулирование и Банк России','Кто организует функционирование платформы цифрового рубля согласно актуальному закону?','["Любая региональная кредитная организация без специальных полномочий","Исключительно Министерство культуры","Представительные органы муниципальных округов","Банк России"]'::jsonb,3,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_37570/4f84b42935e2a5743f1b5e1591668be0c41b762d/','Основание — статья 4 указанного НПА; правильный порядок решения: Банк России.',true),
('Денежно-кредитное регулирование и Банк России','Правительство требует назначить Председателя Банка России своим распоряжением без участия парламента. Какая процедура законна?','["Председателя назначает исключительно Председатель Правительства","Председателя выбирают губернаторы на общем собрании","Государственная Дума назначает по представлению Президента РФ","Председателя назначает Совет Федерации по представлению Банка России"]'::jsonb,2,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_37570/bc1c9aa2b5a88fe1bb1bdb9142a14c25cf7c5cb5/','Основание — статья 5 указанного НПА; правильный порядок решения: Государственная Дума назначает по представлению Президента РФ.',true),
('Денежно-кредитное регулирование и Банк России','Государственная Дума хочет заслушать доклад Председателя Банка России о деятельности регулятора. Допускает ли закон такую процедуру?','["Нет, Банк России подотчётен только финансовым органам субъектов","Да, Дума заслушивает соответствующие доклады","Да, но лишь через муниципальные публичные слушания","Нет, отчётность ЦБ рассматривает исключительно Правительство"]'::jsonb,1,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_37570/bc1c9aa2b5a88fe1bb1bdb9142a14c25cf7c5cb5/','Основание — статья 5 указанного НПА; правильный порядок решения: Да, Дума заслушивает соответствующие доклады.',true),
('Денежно-кредитное регулирование и Банк России','Минфин предлагает ЦБ выдать прямой кредит для закрытия дефицита федерального бюджета, не имея специальной нормы закона о бюджете. Что действует?','["Прямое кредитование дефицита федерального бюджета Банком России запрещено, кроме предусмотренного законом о бюджете исключения","Такие кредиты обязательны при любой нехватке налоговых доходов","Разрешение даёт исключительно региональный парламент","Прямой кредит ЦБ допускается на основании устной просьбы министра"]'::jsonb,0,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_37570/0c316aab7f557c58d610e07c3b879f02138e3322/','Основание — статья 22 указанного НПА; правильный порядок решения: Прямое кредитование дефицита федерального бюджета Банком России запрещено, кроме предусмотренного законом о бюджете исключения.',true),
('Денежно-кредитное регулирование и Банк России','Губернатор просит Банк России покрыть региональный дефицит целевым кредитом. Какое ограничение установлено?','["ЦБ обязан кредитовать любой регион с дефицитом","Такие кредиты допускаются после утверждения местного бюджета","Кредит предоставляется по решению законодательного собрания субъекта","Банку России запрещено кредитовать дефициты бюджетов субъектов РФ"]'::jsonb,3,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_37570/0c316aab7f557c58d610e07c3b879f02138e3322/','Основание — статья 22 указанного НПА; правильный порядок решения: Банку России запрещено кредитовать дефициты бюджетов субъектов РФ.',true),
('Денежно-кредитное регулирование и Банк России','При росте инфляционных рисков Банк России обсуждает изменение обязательных резервных требований. Является ли это законным инструментом ДКП?','["Нет, менять резервные требования может только Госдума","Нет, инструмент применим исключительно к местным бюджетам","Да, резервные требования прямо названы инструментом денежно-кредитной политики","Да, но только после утверждения каждого изменения Советом Федерации"]'::jsonb,2,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_37570/de204ed76805e5c33087b97c5e4c9851924ac898/','Основание — статья 35 указанного НПА; правильный порядок решения: Да, резервные требования прямо названы инструментом денежно-кредитной политики.',true),
('Денежно-кредитное регулирование и Банк России','Регулятор намерен использовать операции на открытом рынке для проведения денежно-кредитной политики. К какой категории относится решение?','["К исключительным полномочиям региональных законодательных собраний","К прямо предусмотренным законом инструментам ДКП Банка России","К видам местных налогов, определяемых муниципалитетом","К запрещённым операциям для Банка России при любых условиях"]'::jsonb,1,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_37570/de204ed76805e5c33087b97c5e4c9851924ac898/','Основание — статья 35 указанного НПА; правильный порядок решения: К прямо предусмотренным законом инструментам ДКП Банка России.',true),
('Денежно-кредитное регулирование и Банк России','Банк России рассматривает валютную интервенцию для задач денежно-кредитной политики. Какая статья называет такой инструмент?','["Статья 35 закона о Банке России","Статья о назначении председателя Госдумы","Статья о региональном референдуме","Статья о создании муниципальных округов"]'::jsonb,0,'Федеральный закон от 10.07.2002 № 86-ФЗ «О Центральном банке Российской Федерации»','статья 35','https://www.consultant.ru/document/cons_doc_LAW_37570/de204ed76805e5c33087b97c5e4c9851924ac898/','Основание — статья 35 указанного НПА; правильный порядок решения: Статья 35 закона о Банке России.',true),
('Бюджетные обязательства и субсидии','Регион выделяет ассигнования на выполнение государственного задания по оказанию услуг населению. Какая группа расходов предусмотрена БК?','["Источники финансирования дефицита, не включаемые в расходы","Исключительно неналоговые доходы бюджета","Обязательная денежная эмиссия региона","Бюджетные ассигнования на оказание государственных услуг и выполнение работ"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 69','https://www.consultant.ru/document/cons_doc_LAW_19702/80a96f4911ad3207ddb6784bce306612adf8613e/','Основание — статья 69 указанного НПА; правильный порядок решения: Бюджетные ассигнования на оказание государственных услуг и выполнение работ.',true),
('Бюджетные обязательства и субсидии','Администрация финансирует закупку оборудования для муниципальных нужд. Как классифицировать такие средства?','["Налоговая льгота получателю бюджетных средств","Только гарантия муниципального долга","Ассигнования на оказание муниципальных услуг и закупки для публичных нужд","Исключительно средства погашения облигаций Банка России"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 69','https://www.consultant.ru/document/cons_doc_LAW_19702/80a96f4911ad3207ddb6784bce306612adf8613e/','Основание — статья 69 указанного НПА; правильный порядок решения: Ассигнования на оказание муниципальных услуг и закупки для публичных нужд.',true),
('Бюджетные обязательства и субсидии','Областной орган хочет оплатить пенсии как отдельную категорию бюджетных ассигнований. Какой подход предусмотрен БК?','["Ассигнования исключительно на парламентский контроль","Ассигнования на социальное обеспечение населения и иные установленные выплаты","Источники финансирования бюджетного дефицита без расходов","Расходы, исключённые из бюджетного законодательства"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 69','https://www.consultant.ru/document/cons_doc_LAW_19702/80a96f4911ad3207ddb6784bce306612adf8613e/','Основание — статья 69 указанного НПА; правильный порядок решения: Ассигнования на социальное обеспечение населения и иные установленные выплаты.',true),
('Бюджетные обязательства и субсидии','Регион планирует перечислить дотацию муниципалитету. К какой группе ассигнований относится операция?','["К предоставлению межбюджетных трансфертов","К налоговому вычету организации","К денежной эмиссии на региональном уровне","К погашению частных корпоративных обязательств"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 69','https://www.consultant.ru/document/cons_doc_LAW_19702/80a96f4911ad3207ddb6784bce306612adf8613e/','Основание — статья 69 указанного НПА; правильный порядок решения: К предоставлению межбюджетных трансфертов.',true),
('Бюджетные обязательства и субсидии','Федеральное ведомство планирует средства на обслуживание государственного долга. Как классифицируется их назначение?','["Исключительно источники финансирования дефицита без расходов","Неналоговые доходы бюджета","Законная компенсация по налоговому вычету","Бюджетные ассигнования на обслуживание государственного долга"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 69','https://www.consultant.ru/document/cons_doc_LAW_19702/80a96f4911ad3207ddb6784bce306612adf8613e/','Основание — статья 69 указанного НПА; правильный порядок решения: Бюджетные ассигнования на обслуживание государственного долга.',true),
('Бюджетные обязательства и субсидии','Регион хочет поддержать частного производителя субсидией, но утверждает, что такая категория получателей вообще не предусмотрена БК. Верно ли?','["Да, субсидии допускаются исключительно между бюджетами","Да, субсидии вправе получать только казённые учреждения","Нет, БК предусматривает субсидии юридическим лицам и индивидуальным предпринимателям при установленных условиях","Нет, все субсидии предоставляются исключительно Центральным банком"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 78','https://www.consultant.ru/document/cons_doc_LAW_19702/1b6959f23cc516d0e11ddc2e213ca2dca83560df/','Основание — статья 78 указанного НПА; правильный порядок решения: Нет, БК предусматривает субсидии юридическим лицам и индивидуальным предпринимателям при установленных условиях.',true),
('Бюджетные обязательства и субсидии','Муниципалитет намерен субсидировать организацию без соответствующего основания и процедуры, предусмотренных бюджетным правом. Что необходимо?','["Ограничиться устным распоряжением главы муниципалитета","Соблюдать установленные бюджетным законодательством основания и порядок предоставления субсидий","Установить выплату приказом частного подрядчика","Выплатить средства с любого счёта без бюджетного оформления"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 78','https://www.consultant.ru/document/cons_doc_LAW_19702/1b6959f23cc516d0e11ddc2e213ca2dca83560df/','Основание — статья 78 указанного НПА; правильный порядок решения: Соблюдать установленные бюджетным законодательством основания и порядок предоставления субсидий.',true),
('Бюджетные обязательства и субсидии','При предоставлении субсидии производителю работ орган бюджета не прописал условия расходования средств. Какой юридический риск ключевой?','["Нарушение предусмотренного БК и актами условий предоставления и использования субсидии","Отсутствие у производителя права иметь банковский счёт","Автоматическое превращение субсидии в налог","Обязательность проведения муниципального референдума"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 78','https://www.consultant.ru/document/cons_doc_LAW_19702/1b6959f23cc516d0e11ddc2e213ca2dca83560df/','Основание — статья 78 указанного НПА; правильный порядок решения: Нарушение предусмотренного БК и актами условий предоставления и использования субсидии.',true),
('Бюджетные обязательства и субсидии','Областное ведомство предлагает считать субсидией частному предприятию любой бюджетный кредит независимо от обязанности возврата. Какое различие важно?','["Любой бюджетный кредит автоматически безвозвратен","Субсидия всегда предполагает возврат суммы с процентами","Оба механизма являются формой денежной эмиссии региона","Субсидия и возвратный бюджетный кредит имеют различные правовые режимы"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 78','https://www.consultant.ru/document/cons_doc_LAW_19702/1b6959f23cc516d0e11ddc2e213ca2dca83560df/','Основание — статья 78 указанного НПА; правильный порядок решения: Субсидия и возвратный бюджетный кредит имеют различные правовые режимы.',true),
('Бюджетные обязательства и субсидии','Регион хочет предусмотреть субсидию производителю товара, но не отразил ассигнования и установленное основание в бюджетном порядке. Каковы следующие действия?','["Перечислить деньги авансом и оформить основание позже","Поручить производителю самостоятельно создать бюджетную статью","Предусмотреть законную бюджетную основу и процедуру субсидирования до предоставления денег","Заменить субсидию устным обязательством финансового ведомства"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 78','https://www.consultant.ru/document/cons_doc_LAW_19702/1b6959f23cc516d0e11ddc2e213ca2dca83560df/','Основание — статья 78 указанного НПА; правильный порядок решения: Предусмотреть законную бюджетную основу и процедуру субсидирования до предоставления денег.',true),
('Бюджетные обязательства и субсидии','В новом законе субъекта создано расходное обязательство, ранее нигде не исполнявшееся, но не указан источник финансирования. Какой дефект?','["Источник всегда определяется автоматически после первого расхода","Акт должен определить источник и порядок исполнения нового расходного обязательства","Достаточно включить обязательство в пресс-релиз","Источник финансирования всегда выбирает получатель субсидии"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 83','https://www.consultant.ru/document/cons_doc_LAW_19702/deb860cae9c5187f73ff9e422a7e77ade2c35946/','Основание — статья 83 указанного НПА; правильный порядок решения: Акт должен определить источник и порядок исполнения нового расходного обязательства.',true),
('Бюджетные обязательства и субсидии','Законодатель вводит новый вид обязательной социальной выплаты с будущего года. Что следует предусмотреть в правовом акте?','["Порядок исполнения и источники финансового обеспечения нового обязательства","Только наименование получателя без указания механизма","Решение муниципальной комиссии о возможном займе","Исключительно срок публикации информации о нововведении"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 83','https://www.consultant.ru/document/cons_doc_LAW_19702/deb860cae9c5187f73ff9e422a7e77ade2c35946/','Основание — статья 83 указанного НПА; правильный порядок решения: Порядок исполнения и источники финансового обеспечения нового обязательства.',true),
('Бюджетные обязательства и субсидии','Регион создаёт обязательство муниципалитета, но не прописывает передачу нужных финансовых ресурсов. Что важно по БК?','["Признать обязательство самофинансируемым без анализа","Объявить источником любой консолидированный бюджет без распределения","Отложить решение о финансировании до истечения трёх лет","При необходимости закрепить порядок передачи ресурсов на соответствующий уровень бюджета"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 83','https://www.consultant.ru/document/cons_doc_LAW_19702/deb860cae9c5187f73ff9e422a7e77ade2c35946/','Основание — статья 83 указанного НПА; правильный порядок решения: При необходимости закрепить порядок передачи ресурсов на соответствующий уровень бюджета.',true),
('Бюджетные обязательства и субсидии','Министерство предлагает увеличить выплаты по существующему виду обязательств в новом нормативном акте без бюджетных источников. Какая процедура необходима?','["Объявить расходы автоматически обеспеченными за счёт Центрального банка","Считать любые выплаты правом ведомства вне бюджета","Задать источники и порядок исполнения увеличенного обязательства с соблюдением бюджетного процесса","Предусмотреть исключительно консультацию регионального парламента"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 83','https://www.consultant.ru/document/cons_doc_LAW_19702/deb860cae9c5187f73ff9e422a7e77ade2c35946/','Основание — статья 83 указанного НПА; правильный порядок решения: Задать источники и порядок исполнения увеличенного обязательства с соблюдением бюджетного процесса.',true),
('Бюджетные обязательства и субсидии','Депутаты хотят создать новую меру поддержки за счёт неопределённых бюджетов разных уровней. Какое уточнение необходимо?','["Оставить неопределённость до первого иска получателя","Определить источники и распределение финансовых обязательств между надлежащими бюджетами","Обязать любой местный орган выплатить пособие из своего резерва","Перенести определение источника на получателей выплат"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 83','https://www.consultant.ru/document/cons_doc_LAW_19702/deb860cae9c5187f73ff9e422a7e77ade2c35946/','Основание — статья 83 указанного НПА; правильный порядок решения: Определить источники и распределение финансовых обязательств между надлежащими бюджетами.',true),
('Налоговые решения и гарантии','Региональная дума предлагает налоговую льготу исключительно для организаций определённой формы собственности без иных различий. Какой принцип следует проверить?','["Недопустимость дифференциации налоговых льгот лишь по форме собственности","Обязательное освобождение от налога только акционерных обществ","Обязательность льгот по гражданству налогоплательщика","Право любого регионального министерства отменять НК РФ"]'::jsonb,0,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Основание — статья 3 указанного НПА; правильный порядок решения: Недопустимость дифференциации налоговых льгот лишь по форме собственности.',true),
('Налоговые решения и гарантии','В экономическом кризисе ведомство предлагает налог, ограничивающий свободное перемещение денег между субъектами РФ. Какова оценка?','["Регион вправе вводить денежные границы без федерального закона","Любое ограничение движения финансовых средств считается налоговой льготой","Налог допустим при положительном сальдо регионального бюджета","Налоги не должны нарушать единое экономическое пространство"]'::jsonb,3,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Основание — статья 3 указанного НПА; правильный порядок решения: Налоги не должны нарушать единое экономическое пространство.',true),
('Налоговые решения и гарантии','Федеральный налоговый закон впервые устанавливает более высокую ответственность задним числом. Допустимо ли это по действию налоговых актов?','["Обратная сила любого ухудшения является обязательной","Обратная сила определяется исключительно решением местной администрации","Акты, ухудшающие положение налогоплательщика в установленных случаях, не имеют обратной силы","Запрет касается лишь неналоговых платежей"]'::jsonb,2,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_19671/431ac8ed77136ef53561af7f6977bc09ec0595a7/','Основание — статья 5 указанного НПА; правильный порядок решения: Акты, ухудшающие положение налогоплательщика в установленных случаях, не имеют обратной силы.',true),
('Налоговые решения и гарантии','Налоговый закон устраняет ответственность за ранее совершённое нарушение. Какая идея действия закона во времени здесь применяется?','["Все налоговые нормы действуют только после будущего референдума","Благоприятные нормы об устранении ответственности обладают обратной силой","Обратную силу имеют только законы, увеличивающие ответственность","Отмена ответственности не влияет на уже совершённые нарушения"]'::jsonb,1,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_19671/431ac8ed77136ef53561af7f6977bc09ec0595a7/','Основание — статья 5 указанного НПА; правильный порядок решения: Благоприятные нормы об устранении ответственности обладают обратной силой.',true),
('Налоговые решения и гарантии','Закон устраняет дополнительную обязанность налогоплательщика и прямо распространяется на ранее возникшие отношения. Как оценить возможность обратной силы?','["Нормы, улучшающие положение плательщика, могут иметь обратную силу при прямом указании закона","Улучшающие нормы никогда не имеют обратной силы","Обратная сила зависит только от согласия регионального казначейства","Все нормы об отмене обязанностей действуют лишь через три года"]'::jsonb,0,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_19671/431ac8ed77136ef53561af7f6977bc09ec0595a7/','Основание — статья 5 указанного НПА; правильный порядок решения: Нормы, улучшающие положение плательщика, могут иметь обратную силу при прямом указании закона.',true),
('Налоговые решения и гарантии','Регион установил налоговую базу в рублях, но ставку выразил без привязки к единице измерения базы. Какое определение важно?','["Ставка является любым фиксированным бюджетным расходом","Налоговая база всегда равна ставке независимо от объекта","Ставку устанавливает исключительно плательщик","Налоговая ставка представляет величину начислений на единицу измерения налоговой базы"]'::jsonb,3,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 53','https://www.consultant.ru/document/cons_doc_LAW_19671/','Основание — статья 53 указанного НПА; правильный порядок решения: Налоговая ставка представляет величину начислений на единицу измерения налоговой базы.',true),
('Налоговые решения и гарантии','Налоговый закон использует площадь участка как характеристику объекта. Что в таком случае представляет налоговая база?','["Денежное вознаграждение должностного лица","Форму бюджетного трансферта","Физическую характеристику объекта налогообложения","Порядок предоставления государственной услуги"]'::jsonb,2,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 53','https://www.consultant.ru/document/cons_doc_LAW_19671/','Основание — статья 53 указанного НПА; правильный порядок решения: Физическую характеристику объекта налогообложения.',true),
('Налоговые решения и гарантии','Федеральный закон разрешил отдельной категории плательщиков не уплачивать часть налога. Как квалифицируется мера?','["Исключительно межбюджетная дотация","Налоговая льгота как предусмотренное законом преимущество","Обязательное условие налоговой задолженности","Бюджетный кредит под рыночный процент"]'::jsonb,1,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 56','https://www.consultant.ru/document/cons_doc_LAW_19671/','Основание — статья 56 указанного НПА; правильный порядок решения: Налоговая льгота как предусмотренное законом преимущество.',true),
('Налоговые решения и гарантии','Муниципальный орган объявил персональную налоговую льготу для одного названного лица вне законной категории. Какой риск нужно проверить?','["Соблюдение установленного НК порядка и запрета индивидуальных налоговых льгот","Автоматическую правомерность любой персональной льготы","Обязанность произвести денежную эмиссию под льготу","Недопустимость любых налоговых льгот по категориям"]'::jsonb,0,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 56','https://www.consultant.ru/document/cons_doc_LAW_19671/','Основание — статья 56 указанного НПА; правильный порядок решения: Соблюдение установленного НК порядка и запрета индивидуальных налоговых льгот.',true),
('Налоговые решения и гарантии','Налоговый акт содержит два несовместимых толкования, устранить противоречие невозможно. Какую позицию обязан учитывать правоприменитель?','["Неясность автоматически толкуется в пользу наибольшего начисления","Неясность решается предпочтением более позднего письма инспектора","Неясность позволяет не устанавливать плательщика вообще","Неустранимая неясность толкуется в пользу налогоплательщика"]'::jsonb,3,'Налоговый кодекс Российской Федерации, часть первая, № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Основание — статья 3 указанного НПА; правильный порядок решения: Неустранимая неясность толкуется в пользу налогоплательщика.',true),
('Публичная власть и антимонопольное регулирование','Региональным актом установлено, что доступ на товарный рынок имеют лишь компании, внесённые в произвольный закрытый список губернатора. Какова оценка?','["Это обязательно для любого рынка при любой форме собственности","Ограничения не оцениваются по 135-ФЗ, если оформлены региональным актом","Возможен запрещённый ограничивающий конкуренцию акт органа власти","Такой список заменяет процедуры федеральной контрактной системы"]'::jsonb,2,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Возможен запрещённый ограничивающий конкуренцию акт органа власти.',true),
('Публичная власть и антимонопольное регулирование','Местная администрация установила необоснованные запреты на работу новых предпринимателей при отсутствии федерального исключения. Что нарушено?','["Правило обязательного назначения сенаторов","Запрет актов и действий органов власти, ограничивающих конкуренцию","Обязанность передать рынок региональному парламенту","Исключительное право муниципалитета вводить любые барьеры"]'::jsonb,1,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Запрет актов и действий органов власти, ограничивающих конкуренцию.',true),
('Публичная власть и антимонопольное регулирование','Федеральное ведомство требует согласовывать каждый частный договор в отрасли, хотя такая процедура не предусмотрена законом. Какой риск?','["Необоснованное ограничение конкуренции актом или действием органа власти","Любое согласование делает рынок автоматически конкурентным","Договоры частных компаний не связаны с антимонопольным законодательством","Орган вправе вводить согласования без правовых оснований"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Необоснованное ограничение конкуренции актом или действием органа власти.',true),
('Публичная власть и антимонопольное регулирование','Областное министерство одновременно регулирует рынок и выступает участником коммерческого оборота без предусмотренного исключения. Что нужно оценить?','["Обязательность такого совмещения для всех министерств","Право министерства исключать конкурентов как хозяйствующий субъект","Исключительно соблюдение сроков бюджетного отчёта","Запрет совмещения функций власти и хозяйствующего субъекта"]'::jsonb,3,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Запрет совмещения функций власти и хозяйствующего субъекта.',true),
('Публичная власть и антимонопольное регулирование','Муниципалитет наделил частную компанию полномочиями государственного контроля без федерального основания. В чём проблема?','["Любая частная компания вправе самостоятельно осуществлять госнадзор","Такая передача является обычной закупкой по 44-ФЗ","Недопустимая передача публичных контрольных функций хозяйствующему субъекту","Закон требует передавать контроль только победителю аукциона"]'::jsonb,2,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Недопустимая передача публичных контрольных функций хозяйствующему субъекту.',true),
('Публичная власть и антимонопольное регулирование','Региональный орган вводит разную административную плату за аналогичный доступ к рынку без экономической причины. Что следует проверить?','["Право органа вводить произвольную плату как конкурентный инструмент","Создание дискриминационных условий и ограничение конкуренции органом власти","Обязательность территориальной дифференциации по политическому статусу","Только возможность перенести дату местного референдума"]'::jsonb,1,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Создание дискриминационных условий и ограничение конкуренции органом власти.',true),
('Публичная власть и антимонопольное регулирование','Ведомственный акт связывает выдачу разрешения с обязательной покупкой услуг одной определённой фирмы без законного основания. Каков риск?','["Предоставление необоснованного преимущества отдельному хозяйствующему субъекту","Автоматическая законность из-за административной формы договора","Необходимость утверждать разрешение Советом Федерации","Исключительно вопрос уплаты транспортного налога"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Предоставление необоснованного преимущества отдельному хозяйствующему субъекту.',true),
('Публичная власть и антимонопольное регулирование','Региональная администрация требует, чтобы конкуренты без законного основания сократили производство ради сохранения цены местного поставщика. Какой запрет применяется?','["Обязанность согласовывать стоимость товара только с муниципалитетом","Право региона регулировать любое производство распоряжением","Автоматическое освобождение администрации от 135-ФЗ","Запрет ограничивающих конкуренцию актов и действий органов власти"]'::jsonb,3,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Запрет ограничивающих конкуренцию актов и действий органов власти.',true),
('Публичная власть и антимонопольное регулирование','Областное министерство и крупная компания заключили договор о закреплении за компанией всего регионального рынка без федерального основания. Что оценить?','["Исключительно нарушение договора муниципального займа","Обязательный механизм поддержки единого экономического пространства","Запрещённое антиконкурентное соглашение органа власти и хозяйствующего субъекта","Законность любого соглашения государства с предприятием"]'::jsonb,2,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_61763/9428e2efe564b3567fcc0cdd8f037a076a65efd6/','Основание — статья 16 указанного НПА; правильный порядок решения: Запрещённое антиконкурентное соглашение органа власти и хозяйствующего субъекта.',true),
('Публичная власть и антимонопольное регулирование','Муниципальная администрация договорилась с перевозчиками не допускать новых игроков на рынок без федерального основания. Какова правовая оценка?','["Любое соглашение администрации с перевозчиками освобождено от оценки конкуренции","Соглашение, ограничивающее доступ на рынок, подпадает под запрет статьи 16","Новый игрок должен согласовать вступление на рынок с конкурентами","Регулирование относится только к налоговому законодательству"]'::jsonb,1,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_61763/9428e2efe564b3567fcc0cdd8f037a076a65efd6/','Основание — статья 16 указанного НПА; правильный порядок решения: Соглашение, ограничивающее доступ на рынок, подпадает под запрет статьи 16.',true),
('Публичная власть и антимонопольное регулирование','Два органа власти согласовали раздел отраслевого рынка по территориям между выбранными компаниями. Какой риск?','["Антиконкурентное соглашение, приводящее к разделу товарного рынка","Допустимое в любом случае территориальное планирование","Обязательное распределение бюджетных дотаций между муниципалитетами","Соглашение о назначении выборов в Госдуму"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_61763/9428e2efe564b3567fcc0cdd8f037a076a65efd6/','Основание — статья 16 указанного НПА; правильный порядок решения: Антиконкурентное соглашение, приводящее к разделу товарного рынка.',true),
('Публичная власть и антимонопольное регулирование','Орган власти и поставщик совместно договорились поддерживать завышенный тариф в сфере без предусмотренного федерального исключения. Что следует применить?','["Любое соглашение с органом власти автоматически делает цену законной","Тариф может назначаться исключительно решением работников поставщика","Положения 135-ФЗ применяются только к соглашениям между частными компаниями","Запрет антиконкурентных соглашений власти и хозяйствующих субъектов о тарифах"]'::jsonb,3,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_61763/9428e2efe564b3567fcc0cdd8f037a076a65efd6/','Основание — статья 16 указанного НПА; правильный порядок решения: Запрет антиконкурентных соглашений власти и хозяйствующих субъектов о тарифах.',true),
('Публичная власть и антимонопольное регулирование','Региональный фонд совместно с хозяйствующими субъектами организует согласованные действия, препятствующие выходу новых участников на рынок. К чему применим запрет?','["Только к соглашениям частных граждан вне предпринимательства","Исключительно к нарушениям публичных слушаний","К согласованным действиям и соглашениям органов и указанных организаций при ограничении конкуренции","Только к недействительным муниципальным выборам"]'::jsonb,2,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_61763/9428e2efe564b3567fcc0cdd8f037a076a65efd6/','Основание — статья 16 указанного НПА; правильный порядок решения: К согласованным действиям и соглашениям органов и указанных организаций при ограничении конкуренции.',true),
('Публичная власть и антимонопольное регулирование','Коммерческая организация, участвующая в оказании муниципальных услуг, устанавливает необоснованное исключительное право для аффилированного подрядчика. Распространяется ли статья 15?','["Нет, статья действует исключительно для федеральных министерств","Да, в соответствующих случаях на организации, участвующие в предоставлении услуг","Нет, статья касается только центрального Банка России","Только при изменении Конституции РФ"]'::jsonb,1,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_61763/871fb1003dab1dd3ef350f8f7f0f0d10ea20b5c6/','Основание — статья 15 указанного НПА; правильный порядок решения: Да, в соответствующих случаях на организации, участвующие в предоставлении услуг.',true),
('Публичная власть и антимонопольное регулирование','Региональный орган и компания договорились о разных тарифах на идентичный товар без экономического обоснования. Какой состав риска?','["Запрещённое соглашение, создающее необоснованное различие тарифов","Автоматическая законность при любом письменном договоре","Обязательная субвенция муниципалитету","Положения только о регистрации партий"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_61763/9428e2efe564b3567fcc0cdd8f037a076a65efd6/','Основание — статья 16 указанного НПА; правильный порядок решения: Запрещённое соглашение, создающее необоснованное различие тарифов.',true),
('Ценообразование и допуск к госзакупкам','Заказчик определяет НМЦК на массовый стандартный товар при наличии конкурентных рыночных предложений. Какой метод закон считает приоритетным?','["Затратный метод при любом товаре без анализа альтернатив","Нормативный метод независимо от предельных цен","Исключительно тарифный метод для всех нерегулируемых товаров","Метод сопоставимых рыночных цен (анализ рынка)"]'::jsonb,3,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_144624/e7bf3fbecc42f2b992c4a2fc6e93c54d4b4979b1/','Основание — статья 22 указанного НПА; правильный порядок решения: Метод сопоставимых рыночных цен (анализ рынка).',true),
('Ценообразование и допуск к госзакупкам','Государство установило регулируемый тариф на приобретаемую коммунальную услугу. Какой метод расчёта НМЦК следует использовать?','["Метод произвольного усреднения предложений без учёта тарифа","Метод расчёта по наибольшей исторической цене","Тарифный метод на основе регулируемой цены","Исключительно оценку имущества на дату закупки"]'::jsonb,2,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_144624/e7bf3fbecc42f2b992c4a2fc6e93c54d4b4979b1/','Основание — статья 22 указанного НПА; правильный порядок решения: Тарифный метод на основе регулируемой цены.',true),
('Ценообразование и допуск к госзакупкам','Закупается продукция, для которой установлены обязательные предельные цены по правилам нормирования. Какой метод может применяться?','["Исключительно метод оценки будущих налоговых доходов","Нормативный метод в предусмотренных законом условиях","Метод формирования личного бюджета должностного лица","Обязательное определение цены по одному коммерческому предложению"]'::jsonb,1,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_144624/e7bf3fbecc42f2b992c4a2fc6e93c54d4b4979b1/','Основание — статья 22 указанного НПА; правильный порядок решения: Нормативный метод в предусмотренных законом условиях.',true),
('Ценообразование и допуск к госзакупкам','Заказчик предлагает обосновать НМЦК исключительно предпочтением местного поставщика без расчёта. Какое требование нарушено?','["Обязанность определить и обосновать НМЦК предусмотренными статьёй 22 методами","Достаточность любого субъективного предложения заказчика","Обязанность использовать исключительно прошлогодний бюджет без обоснования","Право финансового органа произвольно утверждать цену любой закупки"]'::jsonb,0,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_144624/e7bf3fbecc42f2b992c4a2fc6e93c54d4b4979b1/','Основание — статья 22 указанного НПА; правильный порядок решения: Обязанность определить и обосновать НМЦК предусмотренными статьёй 22 методами.',true),
('Ценообразование и допуск к госзакупкам','Рыночный анализ дал несколько сопоставимых предложений, но заказчик выбрал завышенную цену без мотивировки. Какое действие правомерно?','["Использовать максимальную цену без обоснования при любых закупках","Передать расчёт победителю уже после торгов","Заменить расчёт ценой, устно предложенной муниципальным депутатом","Обосновать НМЦК с применением допустимого метода и подтверждённых рыночных данных"]'::jsonb,3,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_144624/e7bf3fbecc42f2b992c4a2fc6e93c54d4b4979b1/','Основание — статья 22 указанного НПА; правильный порядок решения: Обосновать НМЦК с применением допустимого метода и подтверждённых рыночных данных.',true),
('Ценообразование и допуск к госзакупкам','При конкурентной закупке на 25 млн рублей, не подпадающей под исключение, заказчик игнорирует предусмотренное дополнительное требование к опыту. Каков риск?','["Все дополнительные требования запрещены для контрактов свыше 20 млн","Необходимость применять исключительно закупку у единственного поставщика","Нарушение установленного статьёй 31 требования к участникам при таком пороге","Опыт участника никогда не учитывается при государственных закупках"]'::jsonb,2,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 31','https://base.garant.ru/483424149/802464714d4d10a819efb803557e9689/','Основание — статья 31 указанного НПА; правильный порядок решения: Нарушение установленного статьёй 31 требования к участникам при таком пороге.',true),
('Ценообразование и допуск к госзакупкам','При подходящей закупке 20 млн рублей проверяется стоимость ранее исполненного контракта участника. Какой минимальный размер в общем правиле части 2.1?','["Не менее 5 процентов НМЦК","Не менее 20 процентов НМЦК","Не менее 50 процентов НМЦК","Не менее 80 процентов НМЦК"]'::jsonb,1,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 31','https://base.garant.ru/483424149/802464714d4d10a819efb803557e9689/','Основание — статья 31 указанного НПА; правильный порядок решения: Не менее 20 процентов НМЦК.',true),
('Ценообразование и допуск к госзакупкам','Участник представил опыт исполнения сопоставимого контракта за три года до подачи заявки. Какое условие ещё необходимо проверить при применимости части 2.1?','["Надлежащее исполнение обязательств, включая предъявленные неустойки, и установленный размер опыта","Только наименование организации без документов","Членство руководителя в парламентской партии","Обязательное расположение фирмы в одном муниципальном округе"]'::jsonb,0,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 31','https://base.garant.ru/483424149/802464714d4d10a819efb803557e9689/','Основание — статья 31 указанного НПА; правильный порядок решения: Надлежащее исполнение обязательств, включая предъявленные неустойки, и установленный размер опыта.',true),
('Ценообразование и допуск к госзакупкам','Заказчик намерен установить собственный произвольный перечень документов для подтверждения установленных Правительством дополнительных требований. Кто определяет перечень?','["Любое федеральное бюджетное учреждение самостоятельно","Представительный орган муниципалитета для всей России","Победитель торгов после подписания контракта","Правительство Российской Федерации"]'::jsonb,3,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 31','https://base.garant.ru/483424149/802464714d4d10a819efb803557e9689/','Основание — статья 31 указанного НПА; правильный порядок решения: Правительство Российской Федерации.',true),
('Ценообразование и допуск к госзакупкам','Заказчик предлагает включить условия исполнения, не соответствующие извещению и заявке победителя, без предусмотренного исключения. Что требует закон?','["Считать требования извещения необязательными после торгов","Устанавливать любые условия по просьбе бухгалтера","Заключать контракт на согласованных законом условиях закупки и заявки","Заменять контракт односторонним приказом поставщика"]'::jsonb,2,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 34','https://www.consultant.ru/document/Cons_doc_LAW_144624/c5cbc4acc59ffed792a3921dbc18900d2d0f7eb1/','Основание — статья 34 указанного НПА; правильный порядок решения: Заключать контракт на согласованных законом условиях закупки и заявки.',true),
('Ценообразование и допуск к госзакупкам','В рамках закупки с регулируемой государством ценой заказчик предлагает обосновывать цену лишь средней рыночной ценой без учёта тарифа. Какой подход надлежащий?','["Игнорировать регулируемую цену по усмотрению ведомства","Определять цену тарифным методом по установленному регулируемому тарифу","Всегда использовать максимальное предложение из трёх","Назначать цену на основании партийной программы"]'::jsonb,1,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 22','https://www.consultant.ru/document/cons_doc_LAW_144624/e7bf3fbecc42f2b992c4a2fc6e93c54d4b4979b1/','Основание — статья 22 указанного НПА; правильный порядок решения: Определять цену тарифным методом по установленному регулируемому тарифу.',true),
('Ценообразование и допуск к госзакупкам','Правительство утвердило дополнительные требования к участникам определённых закупок. Заказчик заменяет их собственной шкалой без полномочий. Что следует сделать?','["Применить установленные законом и Правительством требования в надлежащих случаях","Сохранить собственные требования даже при конфликте с нормативными","Считать наличие любых дополнительных требований незаконным","Передать определение квалификации только победителю"]'::jsonb,0,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 31','https://base.garant.ru/483424149/802464714d4d10a819efb803557e9689/','Основание — статья 31 указанного НПА; правильный порядок решения: Применить установленные законом и Правительством требования в надлежащих случаях.',true),
('Государственное стратегическое регулирование','Федеральная стратегия и региональная программа используют несовместимые индикаторы, что затрудняет оценку результата. Какую задачу следует реализовать?','["Отказ от измерения индикаторов всех программ","Разделение любого финансирования только по числу исполнителей","Обязательное утверждение региональной программы Конституционным Судом","Координацию стратегического управления и согласование целей и задач"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Основание — статья 8 указанного НПА; правильный порядок решения: Координацию стратегического управления и согласование целей и задач.',true),
('Государственное стратегическое регулирование','Регион намерен профинансировать программу без оценки финансовых возможностей. Какой элемент стратегического планирования недостаточен?','["Указание только фамилии руководителя ведомства","Назначение выборов в региональный парламент","Оценка ограничений, ресурсов и возможностей социально-экономического развития","Издание нового муниципального устава"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Основание — статья 8 указанного НПА; правильный порядок решения: Оценка ограничений, ресурсов и возможностей социально-экономического развития.',true),
('Государственное стратегическое регулирование','Местный план развития выбрал единственную дорогостоящую альтернативу без анализа других путей. Что требует 172-ФЗ?','["Выбрать самую дорогую альтернативу для гарантированного освоения","Выбрать способы достижения целей, обеспечивающие наибольшую эффективность ресурсов","Не сопоставлять способы достижения целевых показателей","Согласовывать выбор только с поставщиком оборудования"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Основание — статья 8 указанного НПА; правильный порядок решения: Выбрать способы достижения целей, обеспечивающие наибольшую эффективность ресурсов.',true),
('Государственное стратегическое регулирование','В отраслевой стратегии предусмотрели рост производства без учёта внешних торговых ограничений и технологических рисков. Какая задача упущена?','["Определение внешних условий, ограничений и угроз развитию","Назначение состава муниципальной избирательной комиссии","Принятие закона о государственной службе субъекта","Только ежегодное утверждение регламента Госдумы"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Основание — статья 8 указанного НПА; правильный порядок решения: Определение внешних условий, ограничений и угроз развитию.',true),
('Государственное стратегическое регулирование','Стратегическое ведомство не согласовало сроки госпрограммы с бюджетной политикой субъекта. Какая задача закона важна?','["Запрет межбюджетных отношений до принятия стратегии","Отмена необходимости прогнозирования доходов","Прямая эмиссия региональных денежных знаков","Координация стратегического управления и мер бюджетной политики"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Основание — статья 8 указанного НПА; правильный порядок решения: Координация стратегического управления и мер бюджетной политики.',true),
('Государственное стратегическое регулирование','Ведомство включило государственную программу РФ в группу документов только прогнозирования. Какова правильная классификация?','["Документ исключительно муниципального целеполагания","Только судебный акт о финансовом контроле","Документ планирования и программирования федерального уровня","Документ конституционного контроля за Правительством"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 11','https://base.garant.ru/70684666/9d78f2e21a0e8d6e5a75ac4e4a939832/','Основание — статья 11 указанного НПА; правильный порядок решения: Документ планирования и программирования федерального уровня.',true),
('Государственное стратегическое регулирование','Министерство предлагает считать национальный проект исключительно документом регионального бюджетного учёта. Как закон классифицирует нацпроекты?','["Документы судебной экспертизы","Федеральные документы планирования и программирования","Исключительно муниципальные планы землепользования","Ненормативные распоряжения финансовых организаций"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 11','https://base.garant.ru/70684666/9d78f2e21a0e8d6e5a75ac4e4a939832/','Основание — статья 11 указанного НПА; правильный порядок решения: Федеральные документы планирования и программирования.',true),
('Государственное стратегическое регулирование','Субъект создал долгосрочный бюджетный прогноз и не относит его к стратегическому планированию. Какова оценка?','["Бюджетный прогноз субъекта относится к документам прогнозирования","Бюджетный прогноз относится только к ведомственным приказам","Долгосрочный прогноз всегда является федеральным конституционным законом","Бюджетный прогноз запрещено утверждать регионам"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 11','https://base.garant.ru/70684666/9d78f2e21a0e8d6e5a75ac4e4a939832/','Основание — статья 11 указанного НПА; правильный порядок решения: Бюджетный прогноз субъекта относится к документам прогнозирования.',true),
('Государственное стратегическое регулирование','Муниципальная программа предусматривает мероприятия по благоустройству, ресурсы и исполнителей. Является ли она документом стратегического планирования?','["Нет, только федеральные государственные программы имеют такой статус","Да, лишь после её принятия Государственной Думой","Нет, муниципалитеты исключены из системы планирования","Да, муниципальные программы включены в перечень документов планирования и программирования"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 11','https://base.garant.ru/70684666/9d78f2e21a0e8d6e5a75ac4e4a939832/','Основание — статья 11 указанного НПА; правильный порядок решения: Да, муниципальные программы включены в перечень документов планирования и программирования.',true),
('Государственное стратегическое регулирование','Группа научных организаций готова помочь подготовить стратегический документ, содержащий охраняемую законом тайну. Какой подход предусмотрен?','["Безусловно открывать им любые сведения без соблюдения ограничений","Запрещать участие научных организаций при любых документах","Привлекать научные организации с соблюдением требований к охраняемой законом тайне","Передавать принятие стратегии научным организациям вместо органов власти"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании в Российской Федерации»','статья 11','https://base.garant.ru/70684666/9d78f2e21a0e8d6e5a75ac4e4a939832/','Основание — статья 11 указанного НПА; правильный порядок решения: Привлекать научные организации с соблюдением требований к охраняемой законом тайне.',true),
('Экономические основы и компетенция власти','Регион вводит экономические правила, полностью запрещающие свободное перемещение услуг по территории России без конституционного основания. Какая гарантия затронута?','["Безусловное право каждого субъекта создавать внутреннюю таможенную границу","Единство экономического пространства и свободное перемещение товаров, услуг и финансовых средств","Исключительная компетенция муниципалитета определять валютные режимы","Право любого региона вводить собственную денежную единицу"]'::jsonb,1,'Конституция Российской Федерации','статья 8','https://minjust.gov.ru/ru/documents/8011/','Основание — статья 8 указанного НПА; правильный порядок решения: Единство экономического пространства и свободное перемещение товаров, услуг и финансовых средств.',true),
('Экономические основы и компетенция власти','Глава субъекта допускает сговор крупных предприятий ради полной монополизации рынка. Какое положение Конституции нарушается?','["Запрет деятельности, направленной на монополизацию и недобросовестную конкуренцию","Обязанность частных компаний иметь государственную долю","Запрет частной предпринимательской деятельности как таковой","Обязательное установление единой цены всеми конкурентами"]'::jsonb,0,'Конституция Российской Федерации','статья 34','https://minjust.gov.ru/ru/documents/8011/','Основание — статья 34 указанного НПА; правильный порядок решения: Запрет деятельности, направленной на монополизацию и недобросовестную конкуренцию.',true),
('Экономические основы и компетенция власти','Законодательное собрание региона пытается установить общие основы кредитного и таможенного регулирования страны своим законом. Как разграничена компетенция?','["Эти вопросы решает исключительно представительный орган муниципалитета","Эти вопросы передаются каждому субъекту без федеральных норм","Ими ведает только Центральная избирательная комиссия","Финансовое, валютное, кредитное и таможенное регулирование относятся к ведению РФ"]'::jsonb,3,'Конституция Российской Федерации','статья 71','https://minjust.gov.ru/ru/documents/8011/','Основание — статья 71 указанного НПА; правильный порядок решения: Финансовое, валютное, кредитное и таможенное регулирование относятся к ведению РФ.',true),
('Экономические основы и компетенция власти','Региональная экономическая программа предлагает игнорировать принципы социального партнёрства и уважения труда при построении целей развития. Какой конституционный ориентир важен?','["Исключительно достижение профицита регионального бюджета","Обязательная передача региональной собственности частным лицам","Сбалансированность прав и обязанностей, социальное партнёрство и уважение человека труда","Замену всех социальных целей денежной эмиссией"]'::jsonb,2,'Конституция Российской Федерации','статья 75.1','https://minjust.gov.ru/ru/documents/8011/','Основание — статья 75.1 указанного НПА; правильный порядок решения: Сбалансированность прав и обязанностей, социальное партнёрство и уважение человека труда.',true),
('Экономические основы и компетенция власти','В федеральной стратегии устойчивый экономический рост объявлен задачей исключительно бизнеса, исключённой из государственных ориентиров. Какая конституционная норма имеет значение?','["Конституция запрещает государственные меры экономического роста","Статья 75.1 предусматривает создание условий устойчивого экономического роста и повышения благосостояния граждан","Конституция относит экономический рост только к ведению муниципалитетов","Статья 75.1 регулирует только федеральную избирательную систему"]'::jsonb,1,'Конституция Российской Федерации','статья 75.1','https://minjust.gov.ru/ru/documents/8011/','Основание — статья 75.1 указанного НПА; правильный порядок решения: Статья 75.1 предусматривает создание условий устойчивого экономического роста и повышения благосостояния граждан.',true)
